// P-code semantics check for the XA module. Reads test/emu/cases.txt (generated by
// test/emu/cases.py), and for each case writes the code at code:001000, sets registers and
// memory, emulates with Ghidra's EmulatorHelper until the PC reaches the end of the main code
// (subroutines may follow it), and compares registers and memory with values worked out by
// hand from the XA User Guide. The "segment" user op (data addresses, see xa.sinc) is
// implemented here as base << 16 | offset, like the segmentop body in xa.pspec.
//
// Each case runs twice: with DS tracked by the disassembler context (dsk=1, dsv=0, the default)
// and with DS dynamic (dsk=0, direct addresses formed from DS at run time), unless the case is
// marked "static" (tracked only). Cases marked "native" or "page0" run only in that language.
//
// Case file lines: case <name> [flags] / code <hex> / end <main-code length in bytes, optional>
//   set <reg> <value> | set <space>:<hexaddr>[/<n>] <value>   (n bytes, little-endian)
//   expect <reg> <value> | expect <space>:<hexaddr>[/<n>] <value>
// Script args: <cases.txt> <outfile>
//@category Testing

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.PrintStream;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.script.GhidraScript;
import ghidra.pcode.emulate.BreakCallBack;
import ghidra.pcode.memstate.MemoryState;
import ghidra.pcode.pcoderaw.PcodeOpRaw;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;
import ghidra.program.model.lang.Register;
import ghidra.program.model.lang.RegisterValue;
import ghidra.program.model.listing.ProgramContext;

public class XAEmuTest extends GhidraScript {

	private static class Case {
		String name;
		String flags = " ";
		byte[] code;
		int mainLen = -1;
		Map<String, Long> set = new LinkedHashMap<>();
		Map<String, Long> expect = new LinkedHashMap<>();
	}

	private List<Case> load(String path) throws Exception {
		List<Case> cases = new ArrayList<>();
		Case c = null;
		try (BufferedReader r = new BufferedReader(new FileReader(path))) {
			String line;
			while ((line = r.readLine()) != null) {
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) {
					continue;
				}
				String[] f = line.split("\\s+");
				switch (f[0]) {
					case "case":
						c = new Case();
						c.name = f[1];
						for (int i = 2; i < f.length; i++) {
							c.flags += f[i] + " ";
						}
						break;
					case "code":
						c.code = new byte[f[1].length() / 2];
						for (int i = 0; i < c.code.length; i++) {
							c.code[i] = (byte) Integer.parseInt(f[1].substring(2 * i, 2 * i + 2), 16);
						}
						break;
					case "main":
						c.mainLen = Integer.decode(f[1]);
						break;
					case "set":
						c.set.put(f[1], Long.decode(f[2]));
						break;
					case "expect":
						c.expect.put(f[1], Long.decode(f[2]));
						break;
					case "end":
						cases.add(c);
						break;
					default:
						throw new IllegalArgumentException("bad line: " + line);
				}
			}
		}
		return cases;
	}

	private Address addr(String loc) {
		String[] p = loc.split("[:/]");
		return currentProgram.getAddressFactory().getAddressSpace(p[0]).getAddress(
			Long.parseLong(p[1], 16));
	}

	private int size(String loc) {
		String[] p = loc.split("/");
		return p.length > 1 ? Integer.parseInt(p[1]) : 1;
	}

	private String runCase(Case c, boolean tracked) throws Exception {
		Address start = addr("code:1000");
		int mainLen = c.mainLen >= 0 ? c.mainLen : c.code.length;
		Address end = start.add(mainLen);
		AddressSet body = new AddressSet(start, start.add(c.code.length + 16));
		clearListing(body);
		setBytes(start, c.code);
		ProgramContext ctx = currentProgram.getProgramContext();
		ctx.setValue(ctx.getRegister("dsk"), start, start.add(c.code.length + 16),
			BigInteger.valueOf(tracked ? 1 : 0));
		ctx.setValue(ctx.getRegister("dsv"), start, start.add(c.code.length + 16), BigInteger.ZERO);
		Register creg = currentProgram.getLanguage().getContextBaseRegister();
		RegisterValue cval = ctx.getRegisterValue(creg, start);

		final EmulatorHelper emu = new EmulatorHelper(currentProgram);
		// segment(base, offset) = base:offset, as declared by the segmentop in xa.pspec
		emu.registerCallOtherCallback("segment", new BreakCallBack() {
			@Override
			public boolean pcodeCallback(PcodeOpRaw op) {
				MemoryState st = emu.getEmulator().getMemState();
				long base = st.getValue(op.getInput(1));
				long inner = st.getValue(op.getInput(2));
				st.setValue(op.getOutput(), ((base & 0xff) << 16) | (inner & 0xffff));
				return true;
			}
		});
		try {
			emu.writeRegister("R7", 0x8000);
			for (Map.Entry<String, Long> e : c.set.entrySet()) {
				if (e.getKey().contains(":")) {
					int n = size(e.getKey());
					byte[] b = new byte[n];
					for (int i = 0; i < n; i++) {
						b[i] = (byte) (e.getValue() >> (8 * i));
					}
					emu.writeMemory(addr(e.getKey()), b);
				}
				else {
					emu.writeRegister(e.getKey(), e.getValue());
				}
			}
			emu.writeRegister(emu.getPCRegister(), start.getOffset());
			emu.setContextRegister(cval);
			int steps = 0;
			while (!emu.getExecutionAddress().equals(end)) {
				if (++steps > 500) {
					return "did not reach the end (pc " + emu.getExecutionAddress() + ")";
				}
				if (!emu.step(monitor)) {
					return "emulation error at " + emu.getExecutionAddress() + ": " +
						emu.getLastError();
				}
			}
			StringBuilder bad = new StringBuilder();
			for (Map.Entry<String, Long> e : c.expect.entrySet()) {
				long got;
				if (e.getKey().contains(":")) {
					int n = size(e.getKey());
					byte[] b = emu.readMemory(addr(e.getKey()), n);
					got = 0;
					for (int i = n - 1; i >= 0; i--) {
						got = (got << 8) | (b[i] & 0xff);
					}
				}
				else {
					got = emu.readRegister(e.getKey()).longValue();
				}
				if (got != e.getValue()) {
					bad.append(String.format(" %s=0x%x (expected 0x%x)", e.getKey(), got,
						e.getValue()));
				}
			}
			return bad.length() == 0 ? null : bad.toString().trim();
		}
		finally {
			emu.dispose();
		}
	}

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		List<Case> cases = load(args[0]);
		PrintStream out = new PrintStream(args[1]);
		String variant = currentProgram.getLanguageID().getIdAsString().endsWith("page0")
				? "page0"
				: "native";
		String other = variant.equals("page0") ? "native" : "page0";
		int pass = 0, fail = 0;
		for (Case c : cases) {
			if (c.flags.contains(" " + other + " ")) {
				continue;
			}
			for (boolean tracked : new boolean[] { true, false }) {
				if (!tracked && c.flags.contains(" static ")) {
					continue;
				}
				String label = c.name + (tracked ? " [DS tracked]" : " [DS dynamic]");
				String err = runCase(c, tracked);
				if (err == null) {
					pass++;
					out.println("PASS " + label);
				}
				else {
					fail++;
					out.println("FAIL " + label + ": " + err);
				}
			}
		}
		out.printf("emulation (%s): %d passed, %d failed%n",
			currentProgram.getLanguageID(), pass, fail);
		out.close();
	}
}
